"use server"

import prisma from "@/lib/db"
import { Prisma } from "@prisma/client"
import { revalidatePath } from "next/cache"

interface RecordPaymentData {
  invoiceId: number
  amount: number
  method: string // 'cash' | 'cheque' | 'transfer' | 'debt_transfer'
  paidByEntityId: number
  chequeNumber?: string
  paymentDate: string
  notes?: string
}

export async function recordPayment(data: RecordPaymentData) {
  try {
    if (data.amount <= 0) {
      return { success: false, message: "Payment amount must be greater than 0." }
    }

    const result = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      // 1. Fetch invoice with lock to prevent race conditions
      // Using a raw query for FOR UPDATE if it was postgres, but for SQLite we don't have row-level locks.
      // We rely on the serializable nature of the transaction or check before update.
      const invoice = await tx.invoice.findUnique({
        where: { id: data.invoiceId },
        include: { entity: true },
      })

      if (!invoice) {
        throw new Error("Invoice not found.")
      }

      if (data.amount > invoice.balance_due) {
        throw new Error(`Amount exceeds balance due (${invoice.balance_due} MAD).`)
      }

      // Check if the payer entity is valid for a debt transfer
      if (data.method === "debt_transfer" && data.paidByEntityId !== invoice.entity_id) {
        const payer = await tx.entity.findUnique({ where: { id: data.paidByEntityId } })
        if (!payer) throw new Error("Payer entity not found.")
      }

      // 2. Create the payment record
      const payment = await tx.payment.create({
        data: {
          invoice_id: data.invoiceId,
          paid_by_entity_id: data.paidByEntityId,
          method: data.method,
          amount: data.amount,
          cheque_number: data.chequeNumber || null,
          payment_date: new Date(data.paymentDate),
          notes: data.notes || null,
        },
      })

      // 3. Update invoice amounts with optimistic locking
      const newAmountPaid = invoice.amount_paid + data.amount
      const newBalanceDue = invoice.total - newAmountPaid
      const newStatus = newBalanceDue <= 0 ? "paid" : newAmountPaid > 0 ? "open" : invoice.status

      const updateResult = await tx.invoice.updateMany({
        where: { 
          id: data.invoiceId,
          balance_due: invoice.balance_due
        },
        data: {
          amount_paid: newAmountPaid,
          balance_due: Math.max(0, newBalanceDue),
          status: newStatus,
        },
      })

      if (updateResult.count === 0) {
        throw new Error("La facture a été modifiée par une autre transaction. Veuillez réessayer.")
      }

      // 4. Update entity balances
      if (data.method === "debt_transfer" && data.paidByEntityId !== invoice.entity_id) {
        // Debt transfer: B (payer) takes on A's (invoice owner) debt.
        // B's debt to the store increases. A's debt to the store decreases.
        await tx.entity.update({
          where: { id: invoice.entity_id },
          data: { balance_due: { decrement: data.amount } }
        })
        await tx.entity.update({
          where: { id: data.paidByEntityId },
          data: { balance_due: { increment: data.amount } }
        })
      } else {
        // Normal payment (cash, cheque, transfer). Always decreases the invoice's entity balance.
        await tx.entity.update({
          where: { id: invoice.entity_id },
          data: { balance_due: { decrement: data.amount } }
        })
      }

      // 5. If debt_transfer or paid by a different entity, create a debt transfer
      if (data.method === "debt_transfer" || data.paidByEntityId !== invoice.entity_id) {
        await tx.debtTransfer.create({
          data: {
            from_entity_id: data.paidByEntityId,
            to_entity_id: invoice.entity_id,
            amount: data.amount,
            related_payment_id: payment.id,
            note: data.notes || `Payment for invoice ${invoice.invoice_number || "#" + invoice.id} transferred`,
          },
        })
      }

      return payment
    })

    revalidatePath(`/invoices/${data.invoiceId}`)
    revalidatePath("/invoices")
    revalidatePath("/dashboard")
    revalidatePath("/clients")

    return { success: true, message: `Payment of ${data.amount} MAD recorded.` }
  } catch (error) {
    console.error("Error recording payment:", error)
    const msg = error instanceof Error ? error.message : "Failed to record payment."
    return { success: false, message: msg }
  }
}

"use client"

import * as React from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { toast } from "sonner"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Checkbox } from "@/components/ui/checkbox"
import { CalendarCheck, Search, FileText, AlertTriangle } from "lucide-react"
import { generateConsolidatedInvoice } from "@/app/actions/month-end"
import { formatCurrency } from "@/lib/utils"

interface PendingEntry {
  id: number
  log_date: string
  qty: number
  unit_price: number
  total: number
  product: { id: number; name: string; reference: string | null; tax_rate: number }
}

interface Entity {
  id: number
  name: string
}

interface EditedPrice {
  [logId: number]: number
}

export function MonthEndClientComponent({
  entries,
  entities,
  currentMonth,
}: {
  entries: PendingEntry[]
  entities: Entity[]
  currentMonth: string
}) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [editedPrices, setEditedPrices] = React.useState<EditedPrice>({})
  const [selectedEntityId, setSelectedEntityId] = React.useState<number>(
    entities[0]?.id || 0
  )
  const [selectedEntryIds, setSelectedEntryIds] = React.useState<Set<number>>(() => {
    const selectedParam = searchParams.get("selected")
    if (selectedParam) {
      const ids = selectedParam.split(",").map(Number).filter((id) => !isNaN(id))
      const validIds = new Set(entries.map((e) => e.id))
      const validSelectedIds = ids.filter((id) => validIds.has(id))
      return new Set(validSelectedIds)
    }
    return new Set(entries.map((e) => e.id))
  })
  const [entitySearch, setEntitySearch] = React.useState("")
  const [entityDropdownOpen, setEntityDropdownOpen] = React.useState(false)
  const [submitting, setSubmitting] = React.useState(false)
  const entityRef = React.useRef<HTMLDivElement>(null)

  function toggleEntry(id: number) {
    const next = new Set(selectedEntryIds)
    if (next.has(id)) next.delete(id)
    else next.add(id)
    setSelectedEntryIds(next)
  }

  function toggleAll() {
    if (selectedEntryIds.size === entries.length) {
      setSelectedEntryIds(new Set())
    } else {
      setSelectedEntryIds(new Set(entries.map((e) => e.id)))
    }
  }

  React.useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (entityRef.current && !entityRef.current.contains(e.target as Node)) {
        setEntityDropdownOpen(false)
      }
    }
    document.addEventListener("mousedown", handleClick)
    return () => document.removeEventListener("mousedown", handleClick)
  }, [])

  const selectedEntity = entities.find((e) => e.id === selectedEntityId)
  const filteredEntities = entities.filter((e) =>
    e.name.toLowerCase().includes(entitySearch.toLowerCase())
  )

  function getPrice(entry: PendingEntry) {
    return editedPrices[entry.id] ?? entry.unit_price
  }

  function getLineTotal(entry: PendingEntry) {
    return entry.qty * getPrice(entry)
  }

  // Only consider entries that belong to the selected entity or are walk-ins (entity null)
  const validEntriesForEntity = entries.filter((e) => {
     // If the entry already belongs to someone else, we shouldn't steal it
     const entryEntityId = (e as any).entity_id // Need to fetch this
     if (entryEntityId && entryEntityId !== selectedEntityId) return false
     return true
  })
  
  const selectedEntriesList = validEntriesForEntity.filter((e) => selectedEntryIds.has(e.id))
  const runningTotal = selectedEntriesList.reduce((sum, e) => sum + getLineTotal(e), 0)
  const taxAmount = selectedEntriesList.reduce((sum, e) => {
    const lineTotal = getLineTotal(e)
    return sum + (Math.round(lineTotal * (e.product.tax_rate / 100) * 100) / 100)
  }, 0)
  const grandTotal = Math.round((runningTotal + taxAmount) * 100) / 100

  async function handleGenerate() {
    if (selectedEntriesList.length === 0 || !selectedEntityId) return
    setSubmitting(true)
    try {
      const lines = selectedEntriesList.map((e) => ({
        logId: e.id,
        productId: e.product.id,
        qty: e.qty,
        catalogPrice: e.unit_price,
        editedPrice: getPrice(e),
      }))
      const result = await generateConsolidatedInvoice(selectedEntityId, lines)
      if (result.success && result.invoiceId) {
        toast.success(result.message)
        router.push(`/invoices/${result.invoiceId}`)
      } else {
        toast.error(result.message)
      }
    } catch {
      toast.error("Erreur inattendue.")
    } finally {
      setSubmitting(false)
    }
  }

  const pricesEdited = Object.keys(editedPrices).length

  return (
    <div className="flex-1 p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <CalendarCheck className="h-8 w-8 text-primary" />
        <div>
          <h1 className="text-3xl font-bold tracking-tight">
            Clôture mensuelle — {currentMonth}
          </h1>
          <p className="text-muted-foreground">
            Traiter les transactions en attente en une facture consolidée
          </p>
        </div>
      </div>

      {/* Alert */}
      <Card className="border-amber-300 bg-amber-50">
        <CardContent className="flex items-center gap-3 p-4">
          <AlertTriangle className="h-5 w-5 text-amber-600 shrink-0" />
          <div>
            <p className="font-semibold text-amber-800">
              {entries.length} transaction(s) non traitée(s)
            </p>
            <p className="text-sm text-amber-700">
              {selectedEntryIds.size} transaction(s) sélectionnée(s) — Total : {formatCurrency(runningTotal)} (hors taxe)
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Step 1: Transaction Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">
            Étape 1 — Réviser et ajuster les prix
            {pricesEdited > 0 && (
              <Badge variant="outline" className="ml-2 border-blue-400 text-blue-600">
                {pricesEdited} prix modifié(s)
              </Badge>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {validEntriesForEntity.length === 0 ? (
            <p className="text-center text-muted-foreground py-8">
              Aucune transaction en attente à traiter pour ce client.
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[50px]">
                    <Checkbox
                      checked={
                        entries.length > 0 && selectedEntryIds.size === entries.length
                      }
                      onCheckedChange={toggleAll}
                      aria-label="Sélectionner tout"
                    />
                  </TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead>Produit</TableHead>
                  <TableHead className="text-center">Qté</TableHead>
                  <TableHead className="w-40">Prix unitaire (MAD)</TableHead>
                  <TableHead className="text-right">Total ligne</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {validEntriesForEntity.map((entry) => {
                  const isEdited =
                    editedPrices[entry.id] !== undefined &&
                    editedPrices[entry.id] !== entry.unit_price
                  const isChecked = selectedEntryIds.has(entry.id)
                  return (
                    <TableRow key={entry.id} className={!isChecked ? "opacity-60" : ""}>
                      <TableCell>
                        <Checkbox
                          checked={isChecked}
                          onCheckedChange={() => toggleEntry(entry.id)}
                          aria-label={`Select transaction ${entry.id}`}
                        />
                      </TableCell>
                      <TableCell className="text-sm">
                        {new Date(entry.log_date).toLocaleDateString("fr-MA")}
                      </TableCell>
                      <TableCell>
                        <div className="font-medium">{entry.product.name}</div>
                        {entry.product.reference && (
                          <div className="text-xs text-muted-foreground">
                            {entry.product.reference}
                          </div>
                        )}
                      </TableCell>
                      <TableCell className="text-center">{entry.qty}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Input
                            type="number"
                            min={0}
                            step={0.01}
                            value={getPrice(entry)}
                            onChange={(e) => {
                              const val = parseFloat(e.target.value) || 0
                              setEditedPrices((prev) => ({ ...prev, [entry.id]: val }))
                            }}
                            className={`w-24 ${isEdited ? "border-blue-400 bg-blue-50" : ""}`}
                          />
                          {isEdited && (
                            <span className="text-xs text-muted-foreground line-through">
                              {entry.unit_price}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="text-right font-medium">
                        {formatCurrency(getLineTotal(entry))}
                      </TableCell>
                    </TableRow>
                  )
                })}
                {/* Running total row */}
                <TableRow className="bg-muted/30 font-bold">
                  <TableCell colSpan={5} className="text-right">
                    Sous-total (Sélection)
                  </TableCell>
                  <TableCell className="text-right">
                    {formatCurrency(runningTotal)}
                  </TableCell>
                </TableRow>
                <TableRow className="font-medium">
                  <TableCell colSpan={5} className="text-right text-sm text-muted-foreground">
                    TVA
                  </TableCell>
                  <TableCell className="text-right text-sm">
                    {formatCurrency(taxAmount)}
                  </TableCell>
                </TableRow>
                <TableRow className="bg-muted/50 font-bold text-lg">
                  <TableCell colSpan={5} className="text-right">
                    Total
                  </TableCell>
                  <TableCell className="text-right">
                    {formatCurrency(grandTotal)}
                  </TableCell>
                </TableRow>
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Step 2: Client Selector */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Étape 2 — Sélectionner le client</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="relative max-w-md" ref={entityRef}>
            <Label className="mb-2 block text-sm">Facturer à</Label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Rechercher un client..."
                className="pl-9"
                value={entityDropdownOpen ? entitySearch : (selectedEntity?.name || "")}
                onChange={(e) => {
                  setEntitySearch(e.target.value)
                  setEntityDropdownOpen(true)
                }}
                onFocus={() => {
                  setEntityDropdownOpen(true)
                  setEntitySearch("")
                }}
              />
            </div>
            {entityDropdownOpen && (
              <div className="absolute z-50 mt-1 w-full rounded-md border bg-popover shadow-lg max-h-48 overflow-y-auto">
                {filteredEntities.map((entity) => (
                  <button
                    key={entity.id}
                    type="button"
                    className={`flex w-full px-3 py-2 text-sm hover:bg-accent text-left ${
                      entity.id === selectedEntityId ? "bg-accent font-medium" : ""
                    }`}
                    onClick={() => {
                      setSelectedEntityId(entity.id)
                      setEntityDropdownOpen(false)
                      setEntitySearch("")
                    }}
                  >
                    {entity.name}
                  </button>
                ))}
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Step 3: Generate */}
      <div className="flex justify-end pb-8">
        <Button
          size="lg"
          disabled={selectedEntriesList.length === 0 || !selectedEntityId || submitting}
          onClick={handleGenerate}
        >
          <FileText className="h-4 w-4 mr-2" />
          {submitting ? "Génération..." : "Générer la facture consolidée"}
        </Button>
      </div>
    </div>
  )
}

export function MonthEndClient(props: {
  entries: PendingEntry[]
  entities: Entity[]
  currentMonth: string
}) {
  return (
    <React.Suspense fallback={<div>Loading...</div>}>
      <MonthEndClientComponent {...props} />
    </React.Suspense>
  )
}

import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

async function main() {
  console.log('Starting database seeding...')

  // 1. Categories
  console.log('Seeding Categories...')
  const categoriesData = ['Power Tools', 'Accessories', 'Spare Parts', 'Measuring Instruments', 'Hand Tools']
  for (const name of categoriesData) {
    await prisma.category.create({
      data: { name }
    })
  }

  const powerToolsId = (await prisma.category.findFirst({ where: { name: 'Power Tools' } }))!.id
  const accessoriesId = (await prisma.category.findFirst({ where: { name: 'Accessories' } }))!.id
  const sparePartsId = (await prisma.category.findFirst({ where: { name: 'Spare Parts' } }))!.id
  
  // 2. Entities
  console.log('Seeding Entities...')
  await prisma.entity.create({
    data: { name: "Client Divers", type: "individual", notes: "Anonymous walk-in catch-all" }
  })
  const chantierAtlas = await prisma.entity.create({
    data: { name: "Chantier Atlas SARL", type: "company", balance_due: 50000 }
  })
  await prisma.entity.create({
    data: { name: "Electro Maghreb", type: "company", balance_due: 12000 }
  })
  await prisma.entity.create({
    data: { name: "M. Karim Benjelloun", type: "individual", notes: "Regular repeat client" }
  })
  const batiPro = await prisma.entity.create({
    data: { name: "Bati-Pro Maroc", type: "company", balance_due: 0, notes: "Regular client, no debt" }
  })
  await prisma.entity.create({
    data: { name: "Bosch Maroc", type: "supplier" }
  })
  
  // 3. Products
  console.log('Seeding Products and Price Tiers...')
  const productsMap: Array<{ sku: string, name: string, price: number, categoryId: number, stock: number }> = [
    { sku: '06011C10K0', name: 'GBM 400', price: 405, categoryId: powerToolsId, stock: 45 },
    { sku: '06011B70K1', name: 'GSB 570', price: 489, categoryId: powerToolsId, stock: 32 },
    { sku: '06012281K1', name: 'GSB 16 RE', price: 936, categoryId: powerToolsId, stock: 28 },
    { sku: '06112721K0', name: 'GBH 2-24 DRE', price: 2094, categoryId: powerToolsId, stock: 15 },
    { sku: '06112A4000', name: 'GBH 2-26 F', price: 2908, categoryId: powerToolsId, stock: 12 },
    { sku: '06013A30K1', name: 'GWS 700', price: 516, categoryId: powerToolsId, stock: 60 },
    { sku: '06013960K5', name: 'GWS 9-115', price: 1212, categoryId: powerToolsId, stock: 40 },
    { sku: '06017D0100', name: 'GWS 14-125 S', price: 1720, categoryId: powerToolsId, stock: 20 },
    { sku: '06013A40K1', name: 'GDC 140 Kit', price: 992, categoryId: accessoriesId, stock: 35 },
    { sku: '1600Z0000F', name: 'FSN 1600', price: 882, categoryId: accessoriesId, stock: 25 },
    { sku: '06019H2100', name: 'Bosch Go II', price: 757, categoryId: powerToolsId, stock: 50 },
    { sku: '06019G80K0', name: 'GSR 120-LI', price: 1449, categoryId: powerToolsId, stock: 22 },
    { sku: '06019F83K0', name: 'GSB 180-LI', price: 1548, categoryId: powerToolsId, stock: 18 },
    { sku: '06019G5223', name: 'GDX 180-LI', price: 3707, categoryId: powerToolsId, stock: 8 },
    { sku: '0601223000', name: 'GGS 5000', price: 1034, categoryId: accessoriesId, stock: 30 },
    { sku: '06019C3000', name: 'GAS 35 L SFC+', price: 8489, categoryId: accessoriesId, stock: 5 },
    { sku: '0601575103', name: 'GSG 300', price: 11157, categoryId: sparePartsId, stock: 6 },
    { sku: '06012980K0', name: 'GSS 2300', price: 829, categoryId: sparePartsId, stock: 38 },
    { sku: '0601292902', name: 'GSS 280 AVE', price: 4168, categoryId: sparePartsId, stock: 10 },
    { sku: '1600A019RK', name: 'GAL 18V-40', price: 441, categoryId: accessoriesId, stock: 55 }
  ]

  const productIds: number[] = []

  for (const item of productsMap) {
    const product = await prisma.product.create({
      data: {
        name: item.name,
        reference: item.sku,
        category_id: item.categoryId,
        stock_qty: item.stock,
      }
    })
    productIds.push(product.id)

    // Tiers: 1-9 (100%), 10-49 (90%), 50+ (82%)
    await prisma.priceTier.createMany({
      data: [
        { product_id: product.id, min_qty: 1, max_qty: 9, unit_price: item.price },
        { product_id: product.id, min_qty: 10, max_qty: 49, unit_price: item.price * 0.90 },
        { product_id: product.id, min_qty: 50, max_qty: null, unit_price: item.price * 0.82 }
      ]
    })
  }

  // 4. Historical Data
  console.log('Seeding Historical Data (Invoices & Daily Sales)...')

  // Generate 25 Invoices between Oct 1 and Dec 31
  const startMs = new Date('2024-10-01').getTime()
  const endMs = new Date('2024-12-31').getTime()
  
  // Specific Unpaid Invoices for Chantier Atlas SARL
  const atlasInvoicesData = [
    { num: 'INV-2024-001', dateMs: startMs + 1000000000 },
    { num: 'INV-2024-002', dateMs: startMs + 2000000000 },
    { num: 'INV-2024-003', dateMs: startMs + 3000000000 }
  ]

  for (const invoice of atlasInvoicesData) {
    const numLines = Math.floor(Math.random() * 2) + 2; // 2 to 3
    const lines = [];
    let subtotal = 0;
    for (let j = 0; j < numLines; j++) {
      const pIdx = Math.floor(Math.random() * productsMap.length);
      const prod = productsMap[pIdx];
      const pid = productIds[pIdx];
      const qty = Math.floor(Math.random() * 5) + 1;
      const lineTotal = qty * prod.price;
      subtotal += lineTotal;
      lines.push({
        product_id: pid,
        qty: qty,
        catalog_price: prod.price,
        unit_price: prod.price,
        line_total: lineTotal
      });
    }
    const tax_amount = Math.round(subtotal * 0.2 * 100) / 100;
    const total = subtotal + tax_amount;

    await prisma.invoice.create({
      data: {
        entity_id: chantierAtlas.id,
        type: 'invoice',
        status: 'open',
        invoice_number: invoice.num,
        issue_date: new Date(invoice.dateMs),
        due_date: new Date(invoice.dateMs + 86400000 * 30),
        subtotal: subtotal,
        tax_rate: 20,
        tax_amount: tax_amount,
        total: total,
        balance_due: total,
        created_at: new Date(invoice.dateMs),
        lines: { create: lines }
      }
    })
  }

  // Generate remaining random invoices for Bati-Pro
  for (let i = 4; i <= 25; i++) {
    const randomMs = startMs + Math.random() * (endMs - startMs)
    const numLines = Math.floor(Math.random() * 2) + 2; // 2 to 3
    const lines = [];
    let subtotal = 0;
    for (let j = 0; j < numLines; j++) {
      const pIdx = Math.floor(Math.random() * productsMap.length);
      const prod = productsMap[pIdx];
      const pid = productIds[pIdx];
      const qty = Math.floor(Math.random() * 5) + 1;
      const lineTotal = qty * prod.price;
      subtotal += lineTotal;
      lines.push({
        product_id: pid,
        qty: qty,
        catalog_price: prod.price,
        unit_price: prod.price,
        line_total: lineTotal
      });
    }
    const tax_amount = Math.round(subtotal * 0.2 * 100) / 100;
    const total = subtotal + tax_amount;
    
    await prisma.invoice.create({
      data: {
        entity_id: batiPro.id,
        type: 'invoice',
        status: 'paid',
        invoice_number: `INV-2024-${i.toString().padStart(3, '0')}`,
        issue_date: new Date(randomMs),
        subtotal: subtotal,
        tax_rate: 20,
        tax_amount: tax_amount,
        total: total,
        amount_paid: total,
        balance_due: 0,
        created_at: new Date(randomMs),
        lines: { create: lines }
      }
    })
  }

  // Daily Sales Logs (~8 per week for 13 weeks = 104 entries)
  const daysIn3Months = 92
  const logId = 1
  for(let day = 0; day < daysIn3Months; day++) {
    const date = new Date(startMs + day * 86400000)
    // Roughly 1-2 entries per day skips weekends
    if(date.getDay() === 0) continue // Skip Sundays
    
    const entriesToday = Math.floor(Math.random() * 3) // 0 to 2
    for(let j=0; j<entriesToday; j++) {
      const pIdx = Math.floor(Math.random() * productsMap.length)
      const prod = productsMap[pIdx]
      const pid = productIds[pIdx]
      const qty = Math.floor(Math.random() * 3) + 1
      
      await prisma.dailySalesLog.create({
        data: {
          log_date: date,
          product_id: pid,
          qty: qty,
          unit_price: prod.price,
          total: qty * prod.price,
          note: "Anonymous walk-in sale",
          created_at: date
        }
      })
    }
  }

  console.log('Seeding completed successfully!')
}

main()
  .catch((e) => {
    console.error(e)
    process.exit(1)
  })
  .finally(async () => {
    await prisma.$disconnect()
  })
